      <header class="topbar">
        <button class="menu-toggle-button icon-button" id="menu-toggle" aria-label="Thu gọn menu" aria-expanded="true" aria-controls="sidebar"><span data-icon="menu"></span></button>
        <div class="breadcrumb"><span>Thư viện</span><span class="crumb-slash">/</span><strong id="page-label">Khám phá</strong></div>
        <div class="top-actions">
          <div class="global-search-wrap"><label class="global-search" role="combobox" aria-expanded="false" aria-controls="global-search-results"><span data-icon="search"></span><input id="global-search" type="search" placeholder="Tìm tên sách, tác giả…" autocomplete="off" aria-autocomplete="list"><kbd>⌘ K</kbd></label><div id="global-search-results" class="global-search-results" role="listbox" hidden></div></div>
          <div class="notification-wrapper" id="notification-wrapper">
            <button class="icon-button notification-button" id="notification-toggle" aria-label="Thông báo" aria-expanded="false" aria-controls="notifications-panel" type="button"><span data-icon="bell"></span><i hidden></i><span class="notification-count" hidden></span></button>
            <section class="notifications-panel" id="notifications-panel" aria-label="Thông báo" hidden>
              <header><strong>Thông báo</strong><button class="link-button" id="notification-read-all" type="button" hidden>Đánh dấu đã đọc</button></header>
              <div class="notifications-list" id="notifications-list" role="log" aria-live="polite" aria-relevant="additions"><p class="notification-empty">Đang tải thông báo…</p></div>
            </section>
          </div>
          <button class="auth-shortcut" id="login-shortcut" data-page="login">Đăng nhập</button>
          <div class="account-dropdown" id="account-dropdown">
            <button class="top-avatar" id="account-toggle" aria-label="Mở menu tài khoản" aria-expanded="false" aria-controls="account-menu">K</button>
            <div class="account-menu" id="account-menu" aria-label="Tài khoản" hidden></div>
          </div>
        </div>
      </header>
